(()=> {
const key="clipconnect-demo-marketplace";
const seed=[{id:"p1",title:"YouTube channel — weekly editing partner",description:"Edit 10–15 minute educational videos with clean pacing, captions and simple motion graphics.",budget:"$250–400",deadline:"3–5 days",client:"Northstar Learning",status:"Open"},{id:"p2",title:"Launch film for a sustainable skincare brand",description:"A 45-second premium product film with color grading and sound design.",budget:"$600–900",deadline:"1–2 weeks",client:"Morrow Studio",status:"Open"},{id:"p3",title:"Animated explainer for a SaaS product",description:"Create a concise 60-second motion-led explainer with clear visual storytelling.",budget:"$400–650",deadline:"1 week",client:"Orbit Tools",status:"Open"}];
const read=()=>{try{return JSON.parse(localStorage.getItem(key))||{projects:seed,proposals:[],portfolio:[]}}catch{return {projects:seed,proposals:[],portfolio:[]}}};
const save=d=>localStorage.setItem(key,JSON.stringify(d));
let data=read(); if(!data.projects)data.projects=seed;if(!data.proposals)data.proposals=[];if(!data.portfolio)data.portfolio=[];
const $=s=>document.querySelector(s), esc=s=>String(s||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const notice=(m)=>{const n=$("#notice");if(n){n.textContent=m;n.hidden=false;setTimeout(()=>n.hidden=true,2600)}};
function renderProjects(target,owner=false){if(!target)return;const list=owner?data.projects:data.projects.filter(p=>p.status==="Open");target.innerHTML=list.length?list.map(p=>'<article class="work-card"><div><span class="work-status">'+esc(p.status)+'</span><h3>'+esc(p.title)+'</h3><p>'+esc(p.description)+'</p><div class="work-meta"><span>'+esc(p.client)+'</span><span>'+esc(p.deadline)+'</span></div></div><div class="work-side"><strong>'+esc(p.budget)+'</strong><small>ESTIMATED BUDGET</small>'+(owner?'<button class="small-action" data-close="'+esc(p.id)+'">'+(p.status==="Open"?"Close brief":"Reopen brief")+'</button>':'<button class="small-action" data-apply="'+esc(p.id)+'">Send proposal ↗</button>')+'</div></article>').join(""):'<p class="empty-state">Nothing here yet. New marketplace activity will appear here.</p>';}
function renderProposals(target,clientView=false){if(!target)return;const rows=clientView?data.proposals:data.proposals.filter(x=>x.editor==="Demo Editor");target.innerHTML=rows.length?rows.map(p=>{const brief=data.projects.find(x=>x.id===p.projectId);return '<article class="work-card"><div><span class="work-status">'+esc(p.status)+'</span><h3>'+esc(brief?brief.title:"Project brief")+'</h3><p>'+esc(p.message)+'</p><div class="work-meta"><span>'+esc(p.editor)+'</span><span>'+esc(p.date)+'</span></div></div><div class="work-side"><strong>'+esc(p.quote||"Quote pending")+'</strong>'+(clientView?'<button class="small-action" data-proposal-status="'+esc(p.id)+'">Accept proposal</button>':'')+'</div></article>'}).join(""):'<p class="empty-state">No proposals yet. They will appear here when an editor applies to one of your briefs.</p>';}
function renderProfiles(){const target=$("#profile-list");if(!target)return;const profiles=[["Alex Rivera","Film & brand editor","Premiere Pro · Color grading","4.9"],["Maya Chen","YouTube & social editor","Short-form · After Effects","5.0"],["Jordan Smith","Motion designer","2D animation · Motion design","4.8"],["Priya Nair","Documentary editor","DaVinci Resolve · Storytelling","4.9"],["Noah Williams","Creator video editor","YouTube · Podcast","4.7"],["Sam Taylor","3D & motion artist","Blender · 3D","5.0"]];target.innerHTML=profiles.map(p=>'<article class="profile-card"><div class="profile-avatar">'+p[0].split(" ").map(x=>x[0]).join("")+'</div><div><h3>'+p[0]+'</h3><p>'+p[1]+'</p><small>'+p[2]+'</small></div><strong>★ '+p[3]+'</strong></article>').join("");}
function renderPortfolio(){const target=$("#portfolio-list");if(!target)return;target.innerHTML=data.portfolio.length?data.portfolio.map((p,i)=>'<article class="work-card"><div><h3>'+esc(p.title)+'</h3><p>'+esc(p.description)+'</p></div><button class="small-action" data-remove-portfolio="'+i+'">Remove</button></article>').join(""):'<p class="empty-state">Your portfolio is empty. Add a sample project to build your demo profile.</p>';}
const projectForm=$("#project-form");if(projectForm)projectForm.addEventListener("submit",e=>{e.preventDefault();const f=new FormData(projectForm);const item={id:"p"+Date.now(),title:f.get("title"),description:f.get("description"),budget:f.get("budget"),deadline:f.get("deadline"),client:"Demo Client",status:"Open"};data.projects.unshift(item);save(data);projectForm.reset();notice("Your demo project is published to the marketplace.");renderProjects($("#owned-projects"),true);});
const own=$("#owned-projects");if(own){renderProjects(own,true);own.addEventListener("click",e=>{const b=e.target.closest("[data-close]");if(!b)return;const p=data.projects.find(x=>x.id===b.dataset.close);if(p){p.status=p.status==="Open"?"Closed":"Open";save(data);renderProjects(own,true);notice("Project status updated.");}});}
const available=$("#available-projects");if(available){renderProjects(available);available.addEventListener("click",e=>{const b=e.target.closest("[data-apply]");if(!b)return;const p=data.projects.find(x=>x.id===b.dataset.apply);if(!p)return;const message=prompt("Add a short proposal message for: "+p.title);if(message===null)return;if(!message.trim()){notice("Please add a short message before submitting.");return;}data.proposals.unshift({id:"a"+Date.now(),projectId:p.id,editor:"Demo Editor",message:message.trim(),quote:"Discuss scope",date:new Date().toLocaleDateString(),status:"Submitted"});save(data);notice("Proposal submitted in the demo marketplace.");});}
const proposals=$("#proposal-list");if(proposals){renderProposals(proposals,true);proposals.addEventListener("click",e=>{const b=e.target.closest("[data-proposal-status]");if(!b)return;const p=data.proposals.find(x=>x.id===b.dataset.proposalStatus);if(p){p.status="Accepted (demo)";save(data);renderProposals(proposals,true);notice("Proposal marked accepted in demo data.");}});}
const apps=$("#application-list");if(apps)renderProposals(apps,false);
const profiles=$("#profile-list");if(profiles)renderProfiles();
const portfolio=$("#portfolio-list");if(portfolio){renderPortfolio();const form=$("#portfolio-form");form?.addEventListener("submit",e=>{e.preventDefault();const f=new FormData(form);data.portfolio.push({title:f.get("title"),description:f.get("description")});save(data);form.reset();renderPortfolio();notice("Portfolio item added.");});portfolio.addEventListener("click",e=>{const b=e.target.closest("[data-remove-portfolio]");if(!b)return;data.portfolio.splice(Number(b.dataset.removePortfolio),1);save(data);renderPortfolio();notice("Portfolio item removed.");});}
const count=(s,n)=>{const el=$(s);if(el)el.textContent=String(n)};
count("[data-count-projects]",data.projects.filter(p=>p.status==="Open").length);count("[data-count-proposals]",data.proposals.length);count("[data-count-applications]",data.proposals.filter(p=>p.editor==="Demo Editor").length);
})();